// my-app/hooks/useMediaQuery.ts
import { useEffect, useState } from "react";

export function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState(false);

  useEffect(() => {
    const media = window.matchMedia(query);
    setMatches(media.matches);

    const listener = (e: MediaQueryListEvent) => setMatches(e.matches);
    media.addEventListener("change", listener);
    return () => media.removeEventListener("change", listener);
  }, [query]);

  return matches;
}
```

SSR-safe because `useState(false)` is the server-side default and `window.matchMedia` is only called inside `useEffect` (client-only). The listener is cleaned up via the returned teardown function, and re-registers whenever `query` changes.

